/* Narrative director: exactly one active case and one actionable question.
   Previous free-roaming tools remain in source, but are not campaign entrances. */
const CAMPAIGN_STORE='tp-islands-season-one-v4';let season=TPCampaign.fresh();
try{const value=JSON.parse(localStorage.getItem(CAMPAIGN_STORE)||'null');if(value&&Number.isInteger(value.current)&&value.current>=0&&value.current<episodes.length&&value.records)season=value}catch{}
let displayEpisode=null,caseFeedback=null,caseHint=0;
window.CampaignActive=true;window.CampaignStatus=()=>`案件 ${season.current+1} · ${currentStep().label}`;document.querySelector('.map').insertAdjacentHTML('beforeend','<div class="campaign-banner"><small>TP INVESTIGATION STORIES</small><b>晶片群島查核事件簿</b><span>第一季 · 被移走的利潤</span></div>');
function saveSeason(){try{localStorage.setItem(CAMPAIGN_STORE,JSON.stringify(season))}catch{}}
function seasonEpisode(i=season.current){return episodes[i]}
function seasonRecord(i=season.current){return TPCampaign.record(season,i)}
function currentStep(){const e=seasonEpisode(),r=seasonRecord();return e.steps[Math.min(r.step,e.steps.length-1)]}
function getFile(e,id){return e.files.find(f=>f.id===id)}
function addFile(r,id){if(id&&!r.files.includes(id))r.files.push(id)}
function clearFeedback(){caseFeedback=null;caseHint=0}
function phaseLabel(s){return {inspect:'接案',document:'讀合約',talk:'訪談',request:'調閱',sequence:'重建',puzzle:'勾稽',verdict:'主張'}[s.kind]}
function renderSeason(){const e=seasonEpisode(),r=seasonRecord(),s=currentStep();window.CampaignLocation={island:r.complete?6:s.island,label:r.complete?'結案審查':s.label,episode:e.id};
$('#passport').setAttribute('aria-label','第一季案件紀錄');$('#passport').innerHTML=`▣ 案件紀錄 <span>${Object.values(season.records).filter(x=>x.complete).length} / ${episodes.length}</span>`;
$('#island-panel').innerHTML=`<div class="season-kicker">晶片群島 · 查核事件簿</div><div class="case-number">CASE ${String(season.current+1).padStart(2,'0')} <span>/ 第一季</span></div><h2 class="active-case-title">${e.title}</h2><p class="active-case-subtitle">${e.subtitle}</p><div class="single-objective"><small>${season.finished?'第一季案卷已封存':r.complete?'本案已完成 · 新線索等待接收':'目前調查目標'}</small><b>${season.finished?`回顧你解開的 ${episodes.length} 件事`:r.complete?'封存本案，再打開下一封信':s.title}</b><p>${r.complete?e.cliffhanger:`${islands[s.island].name} · ${s.label}`}</p></div><button class="primary" id="continue-season">${season.finished?'打開已結案紀錄':r.complete?'查看結案與新線索 →':r.step===0?'接下這份案卷 →':'繼續這件案 →'}</button><button class="text-button season-hint-link" id="map-season-guide">我現在該做什麼？</button><span class="season-save">進度自動保存在本瀏覽器</span>`;
$('#continue-season').onclick=()=>season.finished?showSeasonJournal():r.complete?showSeasonEnding(season.current):openCampaignStep();$('#map-season-guide').onclick=showSeasonGuide;
$('#world-hud').innerHTML=`<div class="campaign-hud-title"><span>🕵️</span><div><b>${e.title}</b><small>${r.complete?'證據、反證與稅基已形成單案紀錄':`正在追查：${e.question}`}</small></div></div><div class="campaign-progress">${e.steps.map((v,i)=>`<span class="${r.solved.includes(i)?'done':i===r.step?'now':''}" title="${v.label}"></span>`).join('')}<small>${r.complete?'已完成':`${r.step+1} / ${e.steps.length} 個現場`}</small></div><button class="text-button" id="hud-evidence">▤ 本案證據袋 ${r.files.length}</button>`;$('#hud-evidence').onclick=()=>showEvidenceBag(season.current);
$('#district').innerHTML=`<div class="season-map-note"><div><div class="eyebrow">ONE CASE, ONE QUESTION AT A TIME</div><h2>${r.complete?'一件事查清楚，下一件事才開始。':`前往 ${islands[s.island].name}，查證下一個問題。`}</h2><p>${r.complete?'結案頁會把查得事實、企業反證、調整所得與稅額放在同一條證據鏈上。':'島嶼仍可自由觀看；本案只開放目前這個調查現場。新人物與新問題，由前一步的發現解鎖。'}</p></div><button class="primary" id="street-season-continue">${r.complete?'回到結案頁':'前往目前現場 →'}</button></div>`;$('#street-season-continue').onclick=()=>r.complete?showSeasonEnding(season.current):openCampaignStep();
$('#world-feed').innerHTML=`<div class="season-principle"><b>本季查核原則</b><span>有疑點 → 查到事實 → 面對反證 → 形成有理由的調整。</span><p>學習成果看的是調整能否被證據支持。支持不調整、排除過度調整及保留補查，也都是重要判斷。</p></div>`;
$('.weather').textContent=`第一季 · 案件 ${season.current+1} · ${s.label}`;window.TPScene?.refresh();saveSeason()}
goIsland=function(i){if(!islands[i])return;explorer.island=i;currentIsland=i;window.TPScene?.focus(i);renderSeason()};
drawWorldMap=function(){window.TPScene?.refresh()};renderDistrict=renderSeason;
function routeCampaign(hit){const r=seasonRecord();if(r.complete){showSeasonEnding(season.current);return}const s=currentStep();if(hit.id!==s.island){goIsland(hit.id);toast(`目前待查的是「${s.label}」，位於${islands[s.island].name}。`);return}goIsland(hit.id);openCampaignStep()}
window.CampaignRoute=routeCampaign;
openCase=function(){openCampaignStep()};renderCase=function(){openCampaignStep()};window.openCPAOffice=function(){const s=currentStep();if(s.island===7)openCampaignStep();else toast('會計師會在本案取得相關資料後提出具體反證；先完成目前目標。')};
function documentCard(f){if(!f)return '';return `<article class="story-document"><div class="file-meta"><b>${f.id}</b><span>${safe(f.date)}</span></div><h3>${safe(f.title)}</h3><small>${safe(f.issuer)} · 虛構教學文據</small><ol>${f.lines.map(l=>`<li>${safe(l)}</li>`).join('')}</ol></article>`}
function dialogueState(r,step,s){return r.dialogues[step]||(r.dialogues[step]={node:s.start,history:[{speaker:s.speaker,text:s.nodes[s.start].text}],used:[]})}
function openCampaignStep(){displayEpisode=season.current;const e=seasonEpisode(),r=seasonRecord(),s=currentStep();if(r.complete){showSeasonEnding(season.current);return}if(s.file)addFile(r,s.file);window.TPScene?.focus(s.island);renderSeason();const body=stepBody(e,r,s);openModal(`案件 ${season.current+1} · ${e.title}`,`<div class="story-header"><div><div class="eyebrow">${e.year} · ${e.authority}</div><h2>${s.title}</h2></div><span class="story-step-count">${r.step+1} / ${e.steps.length}<small>${s.label}</small></span></div><div class="story-location">📍 ${islands[s.island].name}<span>本案目前現場</span></div>${s.narration?`<p class="story-narration">${safe(s.narration)}</p>`:''}${r.step===0?`<div class="story-opening">${e.opening.map(p=>`<p>${safe(p)}</p>`).join('')}</div>`:''}<div class="story-layout"><div class="story-play">${body}<div id="case-feedback" aria-live="polite">${feedbackHTML()}</div></div><aside class="story-casebook"><div class="eyebrow">你正在建立的證據鏈</div><h3>${e.question}</h3><div class="case-trail">${e.steps.map((p,i)=>`<div class="${r.solved.includes(i)?'trail-done':i===r.step?'trail-current':''}"><span>${r.solved.includes(i)?'✓':i===r.step?'●':'○'}</span><div><b>${p.label}</b><small>${i<r.step?'已留下紀錄':i===r.step?'目前現場':'尚未解鎖'}</small></div></div>`).join('')}</div><button class="text-button" id="story-evidence">▤ 打開證據袋</button><button class="text-button" id="story-hint">卡住了，請阿芬提示</button><div id="story-hint-text" class="story-hint-text"></div><p class="case-unit-note">所有金額單位：萬元。人物、交易與文據均為教學假設。</p></aside></div><div class="story-bottom"><button class="text-button" id="return-story-world">← 暫離現場，保留進度</button><button class="text-button" id="story-source">本案專業依據與適用限制 ↗</button></div>`);
$('#story-evidence').onclick=()=>showEvidenceBag(season.current,true);$('#story-hint').onclick=()=>{caseHint++;$('#story-hint-text').textContent=caseHint===1?`方向：${window.TPStoryGuide?.cases[e.id]?.aims[r.step]||s.prompt||e.question}（再按一次看該找哪份資料）`:caseHint===2?(window.TPCaseBriefs?.findHint(e,r,s)||`先比較已取得資料與對方說法，注意：${e.concept}`)+'（再按一次看完整解析）':`完整解析：${s.insight}`};$('#return-story-world').onclick=()=>{$('#modal').close();renderSeason();window.scrollTo({top:0,behavior:'instant'})};$('#story-source').onclick=()=>showEpisodeSources(season.current,true);wireStep(e,r,s);saveSeason()}
function stepBody(e,r,s){if(s.kind==='inspect')return `${documentCard(getFile(e,s.file))}<h3 class="story-question">${s.prompt}</h3><div class="story-choices">${s.options.map((t,i)=>`<button data-story-choice="${i}" ${r.answers[r.step]?.wrong?.includes(i)?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${safe(t)}</button>`).join('')}</div>`;
if(s.kind==='document'){const f=getFile(e,s.file);return `<article class="story-document"><div class="file-meta"><b>${f.id}</b><span>${f.date}</span></div><h3>${f.title}</h3><small>${f.issuer} · 請選出需要追查的條款</small><div class="contract-lines">${f.lines.map((l,i)=>`<button data-story-clause="${i}"><span>§ ${i+1}</span>${safe(l)}</button>`).join('')}</div></article><h3 class="story-question">${s.prompt}</h3>`}
if(s.kind==='request')return `<div class="request-scene"><span>📬</span><div><b>給本案的補充資料通知</b><p>每一份請求都要對應待證事實。這是遊戲文書，不會寄送真實通知。</p></div></div><h3 class="story-question">選擇能回答本案疑點的範圍。</h3><div class="story-choices">${s.options.map((t,i)=>`<button data-story-request="${i}" ${r.answers[r.step]?.wrong?.includes(i)?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${safe(t)}</button>`).join('')}</div>`;
if(s.kind==='talk'){const d=dialogueState(r,r.step,s),node=s.nodes[d.node];return `<div class="authored-dialogue"><div class="authored-character"><span>${s.portrait}</span><div><b>${s.speaker}</b><small>${s.role}</small></div><button class="text-button" id="review-story-talk">訪談筆錄</button></div><div class="dialogue-film" aria-live="polite">${d.history.slice(-4).map(h=>`<div class="authored-line ${h.speaker==='你'?'your-line':''}"><small>${h.speaker}</small><p>${safe(h.text)}</p></div>`).join('')}</div><div class="authored-questions">${node.choices.map((q,i)=>{const needs=q.feedback?.file,locked=needs&&!r.files.includes(needs),used=d.used.includes(d.node+':'+i);return `<button data-dialogue-choice="${i}" ${locked||used?'disabled':''}><span>${locked?'🔒':'→'}</span><div>${safe(q.text)}${locked?`<small>需先取得 ${needs}</small>`:''}</div></button>`}).join('')}${d.node===s.goal?'<div class="conversation-finished">✓ 這段訪談已形成可核對的紀錄；新線索已解鎖。</div>':''}</div></div>${d.exhibit?`<details class="shown-exhibit" open><summary>剛才出示的證據 · ${d.exhibit}</summary>${documentCard(getFile(e,d.exhibit))}</details>`:''}${s.file?documentCard(getFile(e,s.file)):''}`}
if(s.kind==='sequence')return `${documentCard(getFile(e,s.file))}<h3 class="story-question">${s.title}</h3><div class="sequence-puzzle">${s.correct.map((_,i)=>`<label><span>${i+1}</span><select data-sequence-answer="${i}"><option value="">選擇這個時間點發生的事</option>${s.items.map((v,j)=>`<option value="${j}" ${r.answers[r.step]?.values?.[i]===String(j)?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</div><button class="primary" id="check-story-sequence">核對時間與事件 →</button>`;
if(s.kind==='puzzle')return `${documentCard(getFile(e,s.file))}<h3 class="story-question">${s.prompt||s.title}</h3><div class="classification-puzzle">${s.rows.map((row,i)=>`<label><b>${row.label}</b><select data-puzzle-answer="${i}"><option value="">選擇此項的處理理由</option>${row.options.map((v,j)=>`<option value="${j}" ${r.answers[r.step]?.values?.[i]===String(j)?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</div><button class="primary" id="check-story-puzzle">將理由與證據接起來 →</button>`;
if(s.kind==='costBase')return `${documentCard(getFile(e,s.file))}<h3 class="story-question">親手決定本案的成本分母。</h3><div class="cost-basket">${[['engineering','工程及現場成本',6000],['agency','真正純代墊零件',3000],['integrated','在地選配與整合零件',1000]].map(([k,t,n])=>`<label><input type="checkbox" data-cost-item="${k}" value="${n}"><span>${t}</span><b>${n.toLocaleString()} 萬元</b></label>`).join('')}<div id="cost-basket-result">先選擇有功能與可比口徑支持納入的成本。</div></div><button class="primary" id="check-cost-basket">核對分母與可比口徑 →</button>`;
if(s.kind==='profitSplit')return `${documentCard(getFile(e,s.file))}<h3 class="story-question">把例行與剩餘分成兩層計算。</h3><div class="split-board"><p>本案合計利潤 <b>3,000</b> → 先分 JP 例行 <b>200</b>、SG 例行 <b>300</b></p><label>可分割的剩餘利潤<input id="split-residual" type="number" placeholder="3,000 − 200 − 300"></label><p>給定可靠剩餘貢獻因子：JP <b>40%</b>、SG <b>60%</b>。不是通用百分比。</p><label>JP 例行加剩餘的合計應有報酬<input id="split-jp-total" type="number" placeholder="例行 200 ＋ JP 剩餘份額"></label></div><button class="primary" id="check-split-board">核對同一範圍的分割 →</button>`;
if(s.kind==='assetScope')return `${documentCard(getFile(e,s.file))}<h3 class="story-question">哪些是本案證實移轉的標的？</h3><div class="asset-scope">${[['rights','可轉讓的客戶維保權利'],['knowhow','可辨識且實際移交的維修 know-how'],['title','新名片上「支援」兩個字'],['duplicate','已含在移轉包裡的相同未來利益，再加一次']].map(([k,t])=>`<label><input type="checkbox" data-asset-item="${k}"><span>${t}</span></label>`).join('')}<p>本案估值 <b>2,400</b> 已排除標的間的重複價值；已付補償 <b>600</b>。</p></div><button class="primary" id="check-asset-scope">界定移轉包，排除重複 →</button>`;
if(s.kind==='verdict')return `<div class="position-story"><div class="position-formula">${s.formula}</div><label>${s.directTax?'本期已確認的集團淨新增稅額':'你提出的本案調增所得'}（萬元）<input id="story-assessment" type="number" min="0" step="0.01" placeholder="依本案證據計算"></label><fieldset><legend>你在報告中要用哪些理由？</legend>${s.report.map((p,i)=>`<label><input type="checkbox" data-report-basis="${i}">${p}</label>`).join('')}</fieldset><p class="verdict-caution">還有關鍵疑點時可以先補查。這不是輸入愈大就得分愈高的遊戲。<br><small>評分範圍：只核對調整金額、勾選的報告理由和推理板連線；手動追問、筆記等自由文字不計分，只供你回顧。</small></p><button class="primary" id="submit-story-assessment">提出有理由的調整，送結案審查 →</button><button class="text-button" id="story-more-investigation">還有疑點，先保留補查</button></div>`;return ''}
function feedbackHTML(){if(!caseFeedback)return '';return `<div class="story-feedback ${caseFeedback.ok?'supported':'reconsider'}"><b>${caseFeedback.ok?'✿ 一個疑點被拆開了':'🔎 這個推論還接不上'}</b><p>${safe(caseFeedback.text)}</p>${caseFeedback.files?.map(id=>documentCard(getFile(seasonEpisode(),id))).join('')||''}${caseFeedback.ok?'<button class="primary" id="next-story-step">帶著這個發現，前往下一個現場 →</button>':''}</div>`}
function showFeedback(ok,text,files=[]){caseFeedback={ok,text,files};$('#case-feedback').innerHTML=feedbackHTML();if(ok)$('#next-story-step').onclick=advanceStoryStep}
function markSolved(e,r,s){if(!r.solved.includes(r.step))r.solved.push(r.step);saveSeason();showFeedback(true,s.reply||s.insight,s.reveal||[]);renderSeason()}
function recordWrong(r,i){r.answers[r.step]??={};r.answers[r.step].wrong??=[];if(!r.answers[r.step].wrong.includes(i))r.answers[r.step].wrong.push(i);saveSeason()}
function wireStep(e,r,s){const index=season.current;
document.querySelectorAll('[data-story-choice],[data-story-clause],[data-story-request]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.storyChoice??b.dataset.storyClause??b.dataset.storyRequest);if(i===s.correct){if(s.reveal)s.reveal.forEach(id=>addFile(r,id));markSolved(e,r,s)}else{recordWrong(r,i);b.disabled=true;showFeedback(false,s.missteps?.[i]||(s.kind==='request'?'這個範圍未能對應待證事實，或超出必要範圍。請針對本案交易、決策與金額取得資料。':s.kind==='document'?'這一條能說明其他責任，但尚未直接回答本案的未付補償疑點。請再看條款如何分開取消與作業損失。':`先不要由名稱、整體結果或單一形式直接下結論。現在要查的是：${e.question}`))}});
if(s.kind==='talk'){const d=dialogueState(r,r.step,s);document.querySelectorAll('[data-dialogue-choice]').forEach(b=>b.onclick=()=>{const q=s.nodes[d.node].choices[+b.dataset.dialogueChoice],key=d.node+':'+b.dataset.dialogueChoice;if(d.used.includes(key))return;d.used.push(key);if(q.feedback?.file)d.exhibit=q.feedback.file;d.history.push({speaker:'你',text:q.text});d.node=q.next;d.history.push({speaker:s.speaker,text:s.nodes[d.node].text});saveSeason();caseFeedback=null;openCampaignStep()});$('#review-story-talk').onclick=()=>showTalkRecord(index,r.step);if(d.node===s.goal&&!caseFeedback)markSolved(e,r,s)}
if(s.kind==='puzzle')$('#check-story-puzzle').onclick=()=>{const vals=[...document.querySelectorAll('[data-puzzle-answer]')].map(v=>v.value);r.answers[r.step]={values:vals};if(TPCampaign.validatePuzzle(s.rows,vals))markSolved(e,r,s);else{saveSeason();const why=window.TPStoryGuide?.cases[e.id]?.rows||[],off=s.rows.map((row,k)=>vals[k]===String(row.correct)?'':`「${row.label}」${vals[k]===''?'還沒選':'接不上'}，請再看：${why[k]||'這一項對應的文據'}`).filter(Boolean);showFeedback(false,`${off.length} 項還需要修正。${off.join(' ')}`)}};
if(s.kind==='sequence')$('#check-story-sequence').onclick=()=>{const vals=[...document.querySelectorAll('[data-sequence-answer]')].map(v=>v.value);r.answers[r.step]={values:vals};if(TPCampaign.validateSequence(s.correct,vals))markSolved(e,r,s);else{saveSeason();showFeedback(false,'時間線還沒接上。先找開發或最早決策，再對照交付、付款與後續使用，不要把最後的形式倒放成起點。')}};
if(s.kind==='costBase'){const update=()=>{const values=[...document.querySelectorAll('[data-cost-item]:checked')].map(x=>Number(x.value)),base=values.reduce((a,b)=>a+b,0);$('#cost-basket-result').textContent=`你選的分母 ${base.toLocaleString()} × 本案 8% ＝ 應有營業利益 ${base*.08}（尚未代表口徑正確）`};document.querySelectorAll('[data-cost-item]').forEach(x=>x.onchange=update);$('#check-cost-basket').onclick=()=>{const selected=[...document.querySelectorAll('[data-cost-item]:checked')].map(x=>x.dataset.costItem);if(TPCampaign.validateCostBase(selected))markSolved(e,r,s);else showFeedback(false,'請逐項對照 E-03：純代墊 3,000 有排除依據；工程 6,000 與在地整合 1,000 在本案應納入。比較對象也須使用一致口徑。')}};
if(s.kind==='profitSplit')$('#check-split-board').onclick=()=>{const a=$('#split-residual').value,b=$('#split-jp-total').value;if(a!==''&&b!==''&&Number(a)===2500&&Number(b)===1200)markSolved(e,r,s);else showFeedback(false,'先從 3,000 扣兩方例行報酬 500，剩 2,500；JP 再取得本案剩餘 40%，並加回自己的例行 200。不可把 40% 直接乘全部利潤。')};
if(s.kind==='assetScope')$('#check-asset-scope').onclick=()=>{const selected=[...document.querySelectorAll('[data-asset-item]:checked')].map(x=>x.dataset.assetItem);if(TPCampaign.validateAssets(selected))markSolved(e,r,s);else showFeedback(false,'本案已證實的標的是維保權利與 know-how。職稱改變不是獨立資產，同一價值也不能再次加入估值。')};
if(s.kind==='verdict'){ $('#submit-story-assessment').onclick=()=>{const raw=$('#story-assessment').value,amount=Number(raw),basis=[...document.querySelectorAll('[data-report-basis]:checked')];if(basis.length!==s.report.length){showFeedback(false,'稅額需要完整理由。請把查得事實、金額及反證都寫入報告；只選有利於調整的一部分還不夠。');return}if(raw===''||!Number.isFinite(amount)||Math.abs(amount-s.amount)>.001){let message=e.id==='idle'&&amount===1500?'1,500 包含已確認屬當地作業責任的 300。排除這筆，不代表放棄查核，而是避免過度調整。':e.id==='idle'&&amount===1100?'1,100 是分部原虧損，不是已證實的未付補償。請從特定交易差額計算。':`請回到本案橋接：${s.formula}`;showFeedback(false,message);return}r.complete=true;r.result={amount:s.amount,tax:s.directTax?s.amount:TPCampaign.tax(s.taxBase,s.amount),base:s.taxBase};if(!r.solved.includes(r.step))r.solved.push(r.step);saveSeason();clearFeedback();showSeasonEnding(index);renderSeason()};$('#story-more-investigation').onclick=()=>{showFeedback(false,'本案保留補查，所得或稅額尚未作成結論。你可以回證據袋核對原文及筆錄；不會把「未定」當成零，也不開啟下一案。')}}
if(r.solved.includes(r.step)&&s.kind!=='verdict'&&!caseFeedback)showFeedback(true,s.insight,s.reveal||[]);if(caseFeedback?.ok&&$('#next-story-step'))$('#next-story-step').onclick=advanceStoryStep;
}
function rewindStoryStep(){const r=seasonRecord();if(r.complete){if(!window.confirm('這件案子已經結案。回到上一步會重新打開結案判斷；已取得的證據和前面的作答都會保留。要繼續嗎？'))return;r.complete=false;r.sealed=false;r.result=null;season.finished=false}const step=r.step,done=(r.solved||[]).includes(step);if(!done){delete r.answers[step];delete r.dialogues[step]}if(step>0)r.step=step-1;else if(done){toast('已經在第一步。這一步的作答已保留。');return}clearFeedback();saveSeason();renderSeason();const modal=$('#modal');if(modal?.open)modal.close();openCampaignStep()}
function resetStoryCase(){const i=season.current;season.records[i]={step:0,files:[],solved:[],dialogues:{},answers:{},notes:'',complete:false,sealed:false};season.finished=false;clearFeedback();saveSeason();renderSeason();const modal=$('#modal');if(modal?.open)modal.close();openCampaignStep()}
window.rewindStoryStep=rewindStoryStep;window.resetStoryCase=resetStoryCase;
function advanceStoryStep(){const e=seasonEpisode(),r=seasonRecord();if(!r.solved.includes(r.step))return;if(r.step<e.steps.length-1)r.step++;clearFeedback();saveSeason();const next=currentStep();goIsland(next.island);if(window.TPPaperTheater)return;$('#modal').close();toast(`新目標：${next.label}。點目前標記，繼續這件案。`)}
function showTalkRecord(index,step){const e=episodes[index],r=seasonRecord(index),s=e.steps[step],d=r.dialogues[step];openModal('訪談筆錄 · '+s.speaker,`<div class="eyebrow">案件 ${index+1} · ${e.title}</div><h2>${s.speaker} · ${s.role}</h2><div class="full-authored-record">${d.history.map(h=>`<div class="authored-line ${h.speaker==='你'?'your-line':''}"><small>${h.speaker}</small><p>${safe(h.text)}</p></div>`).join('')}</div><p class="case-unit-note">保留原話與澄清，不以語氣或表情認定說謊。</p><button class="primary" id="back-story-talk">回到目前現場 →</button>`);$('#back-story-talk').onclick=()=>index===season.current&&!seasonRecord(index).complete?openCampaignStep():showEvidenceBag(index)}
function showEvidenceBag(index,back=false){const e=episodes[index],r=seasonRecord(index);openModal('證據袋 · '+e.title,`<div class="eyebrow">ONLY WHAT YOU HAVE ACTUALLY DISCOVERED</div><h2>讓每一個推論，都找得到原文。</h2><div class="evidence-bag">${r.files.map(id=>documentCard(getFile(e,id))).join('')||'<p class="lead">目前尚未取得文據，先接下第一份案卷。</p>'}</div>${window.ResidentMinutes?ResidentMinutes.caseBlock([...new Set(e.steps.map(s=>s.island))]):''}<h3>已完成的訪談</h3><div class="transcript-list">${Object.entries(r.dialogues).map(([k,d])=>`<button data-review-talk="${k}">${e.steps[k].portrait} ${e.steps[k].speaker} · ${e.steps[k].label}<small>${d.history.filter(h=>h.speaker==='你').length} 次不同問話</small></button>`).join('')||'<p class="case-unit-note">尚無訪談。</p>'}</div><button class="primary" id="bag-return">${back?'回到目前現場 →':'繼續目前案件 →'}</button>`);document.querySelectorAll('[data-review-talk]').forEach(b=>b.onclick=()=>showTalkRecord(index,+b.dataset.reviewTalk));document.querySelectorAll('[data-case-minute]').forEach(b=>b.onclick=()=>ResidentMinutes.openSaved(b.dataset.caseMinute,()=>showEvidenceBag(index,back)));$('#bag-return').onclick=()=>r.complete?showSeasonEnding(index):openCampaignStep()}
function showSeasonEnding(index){const e=episodes[index],r=seasonRecord(index),s=e.steps.at(-1);if(!r.complete)return;const tax=r.result?.tax??(s.directTax?s.amount:TPCampaign.tax(s.taxBase,s.amount));openModal('結案審查 · '+e.title,`<div class="eyebrow">CASE CLOSED · 一個有理由的結果</div><h2>${e.title}：迷霧解開的地方。</h2><p class="story-ending-lead">${s.closing}</p><div class="story-result"><div><small>${s.directTax?'目前已確認的淨新增稅額':'有證據支持的調增所得'}</small><b>${s.amount.toLocaleString()}<em>萬元</em></b></div>${s.directTax?'':`<div><small>本案簡化條件下的新增稅額</small><b>${tax.toLocaleString()}<em>萬元</em></b></div>`}<div class="result-checks">✓ 事實有來源<br>✓ 反證已回應<br>✓ 金額可勾稽</div></div><div class="tax-story-bridge"><b>${s.directTax?'雙邊稅額橋接':'從調增所得走到新增稅額'}</b><p>${s.formula}</p>${s.directTax?'':`<p>本案調前課稅所得 ${s.taxBase.toLocaleString()} → 調後 ${(s.taxBase+s.amount).toLocaleString()}；簡化稅額 ${Math.max(0,s.taxBase)*.2} → ${Math.max(0,s.taxBase+s.amount)*.2}；新增 ${tax}。使用 20% 假設稅率，未計抵減、虧損扣抵、利息及罰鍰；外國案不是該國法定稅額。</p>`}${e.id==='idle'?'<p class="important-tax-limit">第一案已知另有非受控業務所得 2,600，因此全公司調前所得為 1,500。若改成全公司原本只有虧損 1,100、沒有其他所得，調增 1,200 後所得僅 100，本例新增稅額會是 20，不能仍寫 240。</p>':''}</div><h3>這件案真正教會你的事</h3><div class="ending-learning">${e.concept}<p>${s.insight}</p></div><details class="parallel-case-fold"><summary>如果另一個世界的事實不同，結果會怎樣？</summary><div class="story-parallels">${e.parallels.map(p=>`<article><h4>${p.title}</h4><p>${p.fact}</p>${p.story?`<p class="parallel-story">${p.story}</p>`:''}<b>${p.directTax?'淨新增稅額':`調增所得 ${p.amount}；新增稅額`} ${p.directTax?p.amount:TPCampaign.tax(p.base,p.amount)} 萬元</b><p>${p.why}</p></article>`).join('')}</div><p class="case-unit-note">平行結局改變的是事實與範圍，不是允許在相同證據下任選較低稅額。此處為反事實比較，沒有把本案已取得的文據偷偷替換。</p></details><div class="new-letter"><small>${r.sealed?'已讀過的後續線索':'結案後，才出現的下一封信'}</small><p>${e.cliffhanger}</p></div><div class="choice-row">${index===season.current&&!r.sealed?`<button class="primary" id="seal-story-case">${index===episodes.length-1?'封存第一季全部案卷 →':'封存本案，打開下一封信 →'}</button>`:''}<button class="choice" id="ending-story-evidence">回顧證據鏈</button><button class="choice" id="ending-restart-case">回到最初，重新審一次</button><button class="choice" id="ending-story-sources">專業依據與限制</button></div>`);if($('#seal-story-case'))$('#seal-story-case').onclick=()=>{TPCampaign.seal(season,index,episodes.length);saveSeason();clearFeedback();renderSeason();if(season.finished)showSeasonJournal();else showNextLetter(e)};$('#ending-story-evidence').onclick=()=>showEvidenceBag(index);$('#ending-restart-case').onclick=()=>{if(window.confirm('這會清掉本案已結案的進度，從開場再審一次。')){season.current=index;resetStoryCase()}};$('#ending-story-sources').onclick=()=>showEpisodeSources(index,false)}
function showNextLetter(previous){const e=seasonEpisode();openModal('一件事結束後，新的疑點才浮現',`<div class="eyebrow">A LETTER FROM THE NEXT CASE</div><div class="letter-envelope">✉</div><p class="letter-text">${previous.cliffhanger}</p><h2>${e.title}</h2><p class="lead">${e.subtitle}</p><div class="note">這一次，你要查的是：${e.question}</div><button class="primary" id="accept-next-case">接下這個新事件 →</button>`);$('#accept-next-case').onclick=()=>{$('#modal').close();goIsland(currentStep().island);renderSeason()}}
function showSeasonJournal(){openModal('自由選擇案件',`<h2>選擇想調查的案例</h2><p>所有案件均已開放，各案進度獨立保存，不受測驗成績限制。</p><div class="season-journal">${episodes.map((e,i)=>`<button data-season-record="${i}"><span>${season.records[i]?.complete?'✿':'◉'}</span><div><b>${e.title}</b><p>${e.subtitle}</p></div></button>`).join('')}</div>`);document.querySelectorAll('[data-season-record]').forEach(b=>b.onclick=()=>{season.current=+b.dataset.seasonRecord;season.finished=false;clearFeedback();saveSeason();renderSeason();seasonRecord().complete?showSeasonEnding(season.current):openCampaignStep()})}
function showEpisodeSources(i,back){const e=episodes[i];openModal('專業依據 · '+e.title,`<h2>${e.concept}</h2><p class="lead">本案閱讀座標：${e.oecd}。</p><div class="note">故事中的契約、決策、金額及可靠方法結果都是明列的教學假設。實際案件必須獨立驗證交易、方法、比較資料及估值；遊戲並未完成真實查核或核定。</div><p class="lead">${e.authority.includes('外國')?'本案為外國側概念模擬，20% 不是其法定稅率，亦不套用臺灣調查或核定程序。':'臺灣例示另依國內法處理報核、核定、權利保障及救濟；OECD 不是直接補稅法源。'}罰鍰、利息與其他稅項均另行審認。</p><ul class="source-list"><li><a href="${OECD}" target="_blank" rel="noopener">OECD TPG 2022 原文 ↗</a></li><li><a href="https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0340003" target="_blank" rel="noopener">所得稅法 ↗</a></li><li><a href="https://law.moj.gov.tw/LawClass/LawAll.aspx?PCode=G0340019" target="_blank" rel="noopener">TP 查核準則 ↗</a></li><li><a href="https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0340142" target="_blank" rel="noopener">納稅者權利保護法 ↗</a></li>${e.id==='treaty'?'<li><a href="https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0340125" target="_blank" rel="noopener">適用所得稅協定查核準則 ↗</a></li><li><a href="https://law-out.mof.gov.tw/LawContent.aspx?id=GL010455" target="_blank" rel="noopener">適用所得稅協定相互協議程序作業要點 ↗</a></li><li><a href="https://www.mof.gov.tw/multiplehtml/6590" target="_blank" rel="noopener">財政部相互協議程序專區 ↗</a></li>':''}</ul><p class="case-unit-note">本季聚焦 ${episodes.length} 個經人工編寫、自由選擇的不同主題案件。原有案例庫保留在原始資料，不再混入本季事件入口。來源查閱日：2026-11-01。OECD 頁碼為 2022 年英文官方 PDF 印刷頁，已逐頁對段號勾稽；瀏覽器 #page= 為該 PDF 檔頁碼。</p><button class="primary" id="sources-season-back">${back?'回到目前現場':'回到結案紀錄'} →</button>`);$('#sources-season-back').onclick=()=>back?openCampaignStep():seasonRecord(i).complete?showSeasonEnding(i):openCampaignStep()}
function showSeasonGuide(){const e=seasonEpisode(),r=seasonRecord(),s=currentStep();openModal('阿芬的提示',`<div class="eyebrow">YOUR CURRENT QUESTION</div><h2>先把這一件事查清楚。</h2><p class="lead">主題：跨國企業的利潤，是否按實際功能與風險分配？</p><div class="note"><b>現在的案：</b>${e.title}<br><b>現在的問題：</b>${e.question}<br><b>下一步：</b>${s.title}<br><b>地點：</b>${islands[s.island].name} · ${s.label}</div><p class="lead">先讀眼前證據，選擇下一個可查證的問題。訪談選項會隨新事實前進，問過的內容保留在筆錄。完成本案後，新線索才會送達。</p><p class="case-unit-note">立體場景可旋轉及縮放。NPC 與文據為分支腳本，不使用測謊指數或稅額排行榜。</p><button class="primary" id="guide-season-continue">回到這件案 →</button>`);$('#guide-season-continue').onclick=()=>r.complete?showSeasonEnding(season.current):openCampaignStep()}
document.querySelectorAll('[data-nav]').forEach(b=>{const n=b.dataset.nav;b.textContent={map:'追查主線',chapters:'案件紀錄',sim:'前往現場',lab:'查核指引'}[n];b.onclick=()=>n==='chapters'?showSeasonJournal():n==='lab'?showSeasonGuide():openCampaignStep()});$('#passport').onclick=showSeasonJournal;$('#guide').onclick=showSeasonGuide;$('#sources').onclick=()=>showEpisodeSources(season.current,false);$('.brand').onclick=e=>{e.preventDefault();$('#modal').close();window.scrollTo({top:0,behavior:'instant'});window.TPScene?.home()};$('#all-chapters').onclick=showSeasonJournal;$('#risk-card').onclick=openCampaignStep;
showChapters=showSeasonJournal;showPassport=showSeasonJournal;showTools=showSeasonGuide;renderSeason();
